"use client";
// @zeus-internal
import { useCallback, useEffect, useState } from "react";
export type SessionStatus = "idle" | "connecting" | "listening" | "thinking" | "speaking" | "ended";
export const COPY: Record<SessionStatus, {
    label: string;
    hint: string;
}> = {
    ended: { label: "Session ended", hint: "You can start another conversation anytime." },
    idle: { label: "Ready to talk", hint: "Start a conversation with your agent." },
    connecting: { label: "Connecting\u2026", hint: "" },
    listening: { label: "Listening", hint: "\u201CHelp me make a plan for today.\u201D" },
    thinking: { label: "Thinking\u2026", hint: "Putting the next steps together\u2026" },
    speaking: { label: "Speaking", hint: "\u201CLet\u2019s start with what matters most to you.\u201D" },
};
const NEXT: Partial<Record<SessionStatus, [
    SessionStatus,
    number
]>> = {
    connecting: ["listening", 900],
    listening: ["thinking", 5000],
    thinking: ["speaking", 1800],
    speaking: ["listening", 5200],
};
export function useSession() {
    const [status, setStatus] = useState<SessionStatus>("idle");
    const [muted, setMuted] = useState(false);
    useEffect(() => {
        const step = NEXT[status];
        if (!step || (muted && status === "listening"))
            return;
        const id = window.setTimeout(() => setStatus(step[0]), step[1]);
        return () => window.clearTimeout(id);
    }, [status, muted]);
    const start = useCallback(() => {
        setMuted(false);
        setStatus("connecting");
    }, []);
    const stop = useCallback(() => {
        setStatus("ended");
    }, []);
    const toggleMute = useCallback(() => setMuted((m) => !m), []);
    return { status, muted, start, stop, toggleMute };
}

